UPDATE appointment_order SET status='CHECKED_IN',checked_in_at=CURRENT_TIMESTAMP(3),
checkin_claim_id=#{claimId},version=version+1,updated_at=CURRENT_TIMESTAMP(3)
WHERE id=#{id} AND user_id=#{userId} AND outlet_id=#{outletId}
AND status='CONFIRMED' AND qr_nonce_hash=#{hash}
AND qr_expires_at > CURRENT_TIMESTAMP(3)

UPDATE appointment_order SET status=#{to},version=version+1,updated_at=CURRENT_TIMESTAMP(3),
serving_at=CURRENT_TIMESTAMP(3), completed_at=CURRENT_TIMESTAMP(3), no_show_at=CURRENT_TIMESTAMP(3),
id=id WHERE id=#{id} AND queue_ticket_id=#{ticketId} AND status=#{from}
